package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
// The original implementation scanned the input one character at a time in a
// single loop, mixing header, list and paragraph handling together with a
// number of global flags (header, list, listOpened, he). It was hard to
// follow, so it has been rewritten as a line-oriented parser:
//
//  1. Inline emphasis markers (__bold__ / _italic_) are converted to HTML
//     up front, exactly as before (one pair of each).
//  2. The document is then split into lines and each line is rendered as
//     either a header (1-6 leading '#'), a list item (leading "* ") or a
//     paragraph.
//
// The output for every supported construct is unchanged.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var b strings.Builder
	inList := false
	for _, line := range strings.Split(markdown, "\n") {
		if level := headerLevel(line); level > 0 {
			closeList(&b, &inList)
			fmt.Fprintf(&b, "<h%d>%s</h%d>", level, line[level+1:], level)
			continue
		}
		if strings.HasPrefix(line, "* ") {
			if inList {
				b.WriteString("</li>")
			} else {
				inList = true
				b.WriteString("<ul>")
			}
			b.WriteString("<li>" + line[2:])
			continue
		}
		closeList(&b, &inList)
		fmt.Fprintf(&b, "<p>%s</p>", line)
	}
	closeList(&b, &inList)
	return b.String()
}

// applyEmphasis converts the first __...__ and _..._ pairs to <strong> and
// <em>. This preserves the original global replacement behavior.
func applyEmphasis(markdown string) string {
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)
	return markdown
}

// headerLevel reports the level (1-6) of a markdown header line, or 0 if the
// line is not a header. Seven or more leading '#' characters are not a
// header and are rendered as a paragraph, matching the original behavior.
func headerLevel(line string) int {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 0 || level > 6 {
		return 0
	}
	if level == len(line) || line[level] != ' ' {
		return 0
	}
	return level
}

// closeList terminates an open list, if any.
func closeList(b *strings.Builder, inList *bool) {
	if *inList {
		b.WriteString("</li></ul>")
		*inList = false
	}
}
